function initViewer(){

  document.getElementById("orbitalBgColorPicker").value = viewerBgColor;

  viewer = BeeMolMoleculeThree.createViewer("viewer", {

    backgroundColor: viewerBgColor,

    disableFog: true

  });

  viewer.setViewStyle({style: "none"});

  document.getElementById("viewer").style.background = viewerBgColor;

  viewer.render();

}

function setViewerBackground(color){

  viewerBgColor = color;

  document.getElementById("viewer").style.background = color;

  if(viewer){

    viewer.setBackgroundColor(color);

    viewer.render();

  }

}

function setOrbitalStatus(message, isError=false){

  const status = document.getElementById("orbitalStatus");

  if(!status) return;

  status.textContent = message;

  status.style.color = isError ? "var(--danger)" : "var(--muted)";

}

async function initOrbitalViewer() {

  const host = document.getElementById("orbitalViewer");

  if (!host) {

    setOrbitalStatus("Orbital viewer container not found.", true);

    return false;

  }

  try {

    if (!window.BeeMolThree) {

      throw new Error("Three.js orbital renderer is not loaded.");

    }

    const loaded = await window.BeeMolThree.ready;

    if (loaded === false) {

      throw new Error("Three.js could not initialize.");

    }

    orbitalViewerReady = true;

    window.BeeMolThree.resize();

    setOrbitalStatus("Three.js viewer ready. Open a Molden file.");

    return true;

  } catch (error) {

    orbitalViewerReady = false;

    setOrbitalStatus(

      "Could not start Three.js viewer: " + error.message,

      true

    );

    return false;

  }

}

function ensureOrbitalViewer() {

  if (!orbitalViewerReady || !window.BeeMolThree) {

    setOrbitalStatus(

      "Three.js viewer is not ready.",

      true

    );

    return false;

  }

  return true;

}

function getOrbitalSettings(){

  let cutoff =

    Number(document.getElementById("orbitalCutoff").value);

  let translucency =

    Number(document.getElementById("orbitalTranslucency").value);

  if(!Number.isFinite(cutoff)){

    cutoff = 0.03;

  }

  if(!Number.isFinite(translucency)){

    translucency = 0.35;

  }

  cutoff = Math.min(0.5, Math.max(0.0001, cutoff));

  translucency = Math.min(0.95, Math.max(0, translucency));

  const negative =

    document.getElementById("orbitalNegativeColor").value;

  const positive =

    document.getElementById("orbitalPositiveColor").value;

  return {

    cutoff,

    translucency,

    negative,

    positive

  };

}

function orbitalStyleScript(){

  const settings = getOrbitalSettings();

  return (

    `MO COLOR ${settings.negative} ${settings.positive};` +

    `MO translucent ${settings.translucency};` +

    `MO fill nodots nomesh;` +

    `MO titleformat "";`

  );

}

// Parses the [MO] blocks of a Molden file ourselves, independent of Jmol,

// so the orbital list doesn't depend on Jmol's internal (undocumented)

// property paths. Each MO block looks like:

//   Sym= A

//   Ene=      -1234.56789

//   Spin= Alpha

//   Occup=    2.00000

//   1   0.123...

//   2  -0.456...

// "Sym=" is optional in some Molden files, so a new block also starts

// whenever a second "Ene=" line is seen.

function parseMoldenOrbitals(text){

  const orbitals = [];

  let current = null;

  const flush = ()=>{

    if(current && current.energy !== null){

      orbitals.push(current);

    }

    current = null;

  };

  const lines = text.split(/\r?\n/);

  for(const rawLine of lines){

    const line = rawLine.trim();

    if(!line) continue;

    const symMatch = line.match(/^Sym\s*=\s*(.+)$/i);

    if(symMatch){

      flush();

      current = {sym: symMatch[1].trim(), energy: null, spin: null, occup: null};

      continue;

    }

    const eneMatch = line.match(/^Ene\s*=\s*([-+0-9.eEdD]+)/i);

    if(eneMatch){

      if(current && current.energy !== null) flush();

      if(!current) current = {sym: null, energy: null, spin: null, occup: null};

      current.energy = Number(eneMatch[1].replace(/[dD]/, "e"));

      continue;

    }

    if(!current) continue;

    const spinMatch = line.match(/^Spin\s*=\s*(\w+)/i);

    if(spinMatch){ current.spin = spinMatch[1]; continue; }

    const occMatch = line.match(/^Occup\s*=\s*([-+0-9.eEdD]+)/i);

    if(occMatch){ current.occup = Number(occMatch[1].replace(/[dD]/, "e")); continue; }

  }

  flush();

  return orbitals;

}

// Renders the orbital number / energy / occupancy / spin table in the right panel.

function renderOrbitalList(orbitals){

  const body = document.getElementById("orbitalListBody");

  const countLabel = document.getElementById("orbitalListCount");

  if(!body || !countLabel) return;

  body.innerHTML = "";

  if(!Array.isArray(orbitals) || !orbitals.length){

    countLabel.textContent = "0 orbitals";

    return;

  }

  countLabel.textContent = `${orbitals.length} orbitals`;

  const frag = document.createDocumentFragment();

  orbitals.forEach((mo, i)=>{

    const n = i + 1;

    const energy = Number.isFinite(mo.energy) ? mo.energy.toFixed(5) : "—";

    const occ = Number.isFinite(mo.occup) ? mo.occup.toFixed(5) : "—";

    const spin = mo.spin || "—";

    const tr = document.createElement("tr");

    tr.dataset.orbital = n;

    tr.innerHTML = `<td>${n}</td><td>${energy}</td><td>${occ}</td><td>${spin}</td>`;

    tr.addEventListener("click", ()=>{

      document.getElementById("orbitalNumber").value = n;

      showOrbitalNumber();

      markActiveOrbitalRow(n);

    });

    frag.appendChild(tr);

  });

  body.appendChild(frag);

}

function markActiveOrbitalRow(n){

  const body = document.getElementById("orbitalListBody");

  if(!body) return;

  body.querySelectorAll("tr.active-orbital").forEach(tr=>

    tr.classList.remove("active-orbital")

  );

  const row = body.querySelector(`tr[data-orbital="${n}"]`);

  if(row){

    row.classList.add("active-orbital");

    // Do not move the page or viewer while the animation advances.

    if(!animationRunning)row.scrollIntoView({block:"nearest"});

  }

}

// Handles a Molden file picked via the real <input type="file">. We read

// and parse it ourselves (for the orbital list) and hand the same raw text

// to Jmol as inline DATA so it can render the isosurfaces -- this avoids

// relying on Jmol's "load ?" native file dialog, which is often blocked in

// sandboxed/embedded previews.

async function loadEmbeddedOrbital(number){

  const n = Number(number);

  if(!suppliedMoldenModel) suppliedMoldenModel=parseMoldenForGrid(SUPPLIED_MOLDEN);

  if(!Number.isInteger(n) || n<1 || n>suppliedMoldenModel.orbitals.length){

    setOrbitalStatus(`Choose an orbital from 1 to ${suppliedMoldenModel.orbitals.length}.`,true); return;

  }

  embeddedActive=true;

  const token=++orbitalLoadToken;

  const detail=gridDimensions();

  setOrbitalStatus(`Calculating orbital ${n} on the ${detail} grid…`);

  try{

    const cube=await moldenOrbitalCube(suppliedMoldenModel,n,detail,(done,total)=>{

      if(token===orbitalLoadToken)setOrbitalStatus(`Calculating orbital ${n}: ${Math.round(100*done/total)}%`);

    },()=>token===orbitalLoadToken);

    if(token!==orbitalLoadToken)return;

    await handleCubeFile(new File([cube],`orbital_${String(n).padStart(2,"0")}.cube`,{type:"text/plain"}),true,true);

    renderOrbitalList(suppliedMoldenModel.orbitals);

    markActiveOrbitalRow(n);

    setOrbitalStatus(`Orbital ${n} displayed. Change the cutoff to adjust its surface.`);

  }catch(error){setOrbitalStatus(`Could not display orbital ${n}: ${error.message}`,true);console.error(error)}

}

